/// What only Rust can perform for FileProcessing: one required method per bespoke verb and per function its
/// expressions call, no default body, so a missing one is a build error that names it.
#[async_trait]
pub trait FileProcessingActions: Send + Sync {
    /// The verb `start_job`, called by step `mark_running`. `params` are the step's parameters, rendered;
    /// `wf` is the instance's context. The answer is the step's `result`. A refusal the caller can fix
    /// (`Validation`, `NotFound`, `Violations`) is not retried; any other error is.
    async fn start_job(&self, ctx: &WriteCtx, params: &Value, wf: &Value) -> ServiceResult<Value>;

    /// The verb `generate_image_thumbnail`, called by step `process_image_thumbnail`. `params` are the step's parameters, rendered;
    /// `wf` is the instance's context. The answer is the step's `result`. A refusal the caller can fix
    /// (`Validation`, `NotFound`, `Violations`) is not retried; any other error is.
    async fn generate_image_thumbnail(&self, ctx: &WriteCtx, params: &Value, wf: &Value) -> ServiceResult<Value>;

    /// The verb `store_file`, called by steps `store_image_thumbnail`, `store_video_thumbnail`, `store_document_preview`, `store_compressed_file`. `params` are the step's parameters, rendered;
    /// `wf` is the instance's context. The answer is the step's `result`. A refusal the caller can fix
    /// (`Validation`, `NotFound`, `Violations`) is not retried; any other error is.
    async fn store_file(&self, ctx: &WriteCtx, params: &Value, wf: &Value) -> ServiceResult<Value>;

    /// The verb `extract_video_frame`, called by step `process_video_thumbnail`. `params` are the step's parameters, rendered;
    /// `wf` is the instance's context. The answer is the step's `result`. A refusal the caller can fix
    /// (`Validation`, `NotFound`, `Violations`) is not retried; any other error is.
    async fn extract_video_frame(&self, ctx: &WriteCtx, params: &Value, wf: &Value) -> ServiceResult<Value>;

    /// The verb `generate_document_preview`, called by step `process_document_preview`. `params` are the step's parameters, rendered;
    /// `wf` is the instance's context. The answer is the step's `result`. A refusal the caller can fix
    /// (`Validation`, `NotFound`, `Violations`) is not retried; any other error is.
    async fn generate_document_preview(&self, ctx: &WriteCtx, params: &Value, wf: &Value) -> ServiceResult<Value>;

    /// The verb `compress_file`, called by step `process_compression`. `params` are the step's parameters, rendered;
    /// `wf` is the instance's context. The answer is the step's `result`. A refusal the caller can fix
    /// (`Validation`, `NotFound`, `Violations`) is not retried; any other error is.
    async fn compress_file(&self, ctx: &WriteCtx, params: &Value, wf: &Value) -> ServiceResult<Value>;

    /// The verb `scan_file_for_threats`, called by step `process_virus_scan`. `params` are the step's parameters, rendered;
    /// `wf` is the instance's context. The answer is the step's `result`. A refusal the caller can fix
    /// (`Validation`, `NotFound`, `Violations`) is not retried; any other error is.
    async fn scan_file_for_threats(&self, ctx: &WriteCtx, params: &Value, wf: &Value) -> ServiceResult<Value>;

    /// The verb `quarantine_file`, called by step `update_scan_threat`. `params` are the step's parameters, rendered;
    /// `wf` is the instance's context. The answer is the step's `result`. A refusal the caller can fix
    /// (`Validation`, `NotFound`, `Violations`) is not retried; any other error is.
    async fn quarantine_file(&self, ctx: &WriteCtx, params: &Value, wf: &Value) -> ServiceResult<Value>;

    /// The verb `calculate_file_hash`, called by step `process_deduplication`. `params` are the step's parameters, rendered;
    /// `wf` is the instance's context. The answer is the step's `result`. A refusal the caller can fix
    /// (`Validation`, `NotFound`, `Violations`) is not retried; any other error is.
    async fn calculate_file_hash(&self, ctx: &WriteCtx, params: &Value, wf: &Value) -> ServiceResult<Value>;

    /// The verb `complete_job`, called by step `mark_complete`. `params` are the step's parameters, rendered;
    /// `wf` is the instance's context. The answer is the step's `result`. A refusal the caller can fix
    /// (`Validation`, `NotFound`, `Violations`) is not retried; any other error is.
    async fn complete_job(&self, ctx: &WriteCtx, params: &Value, wf: &Value) -> ServiceResult<Value>;

    /// The verb `requeue_job`, called by step `schedule_retry`. `params` are the step's parameters, rendered;
    /// `wf` is the instance's context. The answer is the step's `result`. A refusal the caller can fix
    /// (`Validation`, `NotFound`, `Violations`) is not retried; any other error is.
    async fn requeue_job(&self, ctx: &WriteCtx, params: &Value, wf: &Value) -> ServiceResult<Value>;

    /// The verb `fail_job`, called by step `mark_failed`. `params` are the step's parameters, rendered;
    /// `wf` is the instance's context. The answer is the step's `result`. A refusal the caller can fix
    /// (`Validation`, `NotFound`, `Violations`) is not retried; any other error is.
    async fn fail_job(&self, ctx: &WriteCtx, params: &Value, wf: &Value) -> ServiceResult<Value>;

    /// The verb `delete_file`, called by steps `cleanup_partial_storage`, `cleanup_thumbnails`. `params` are the step's parameters, rendered;
    /// `wf` is the instance's context. The answer is the step's `result`. A refusal the caller can fix
    /// (`Validation`, `NotFound`, `Violations`) is not retried; any other error is.
    async fn delete_file(&self, ctx: &WriteCtx, params: &Value, wf: &Value) -> ServiceResult<Value>;

    /// The function `exponential_backoff(..)` an expression of the workflow calls.
    async fn fn_exponential_backoff(&self, ctx: &WriteCtx, args: &[Value]) -> ServiceResult<Value>;
}

/// The definition the engine runs.
pub struct FileProcessingWorkflow {
    #[allow(dead_code)]
    services: Arc<WorkflowServices>,
    #[allow(dead_code)]
    actions: Arc<dyn FileProcessingActions>,
}

impl FileProcessingWorkflow {
    /// A definition writing through `services` and calling `actions` for what the schema cannot say.
    pub fn new(services: Arc<WorkflowServices>, actions: Arc<dyn FileProcessingActions>) -> Self {
        Self { services, actions }
    }
}

fn to_json<T: serde::Serialize>(value: &T) -> ServiceResult<Value> {
    serde_json::to_value(value).map_err(|e| ServiceError::Internal(e.to_string()))
}

#[allow(dead_code)]
fn record_id(call: &Call<'_>) -> ServiceResult<String> {
    call.id.clone().ok_or_else(|| ServiceError::Validation(format!("step `{}` names no record", call.step)))
}

/// The parameters of a step as fields to write: everything but the record's `id`.
#[allow(dead_code)]
fn fields_of(params: &Value) -> HashMap<String, Value> {
    params.as_object().cloned().unwrap_or_default().into_iter().filter(|(k, _)| k != "id").collect()
}

/// The parameters of a `query` or `fetch` as equality filters, a page size and a sort.
#[allow(dead_code)]
fn filters_of(params: &Value, default_limit: u32) -> (HashMap<String, String>, u32) {
    let mut filters = HashMap::new();
    let mut limit = default_limit;
    for (k, v) in params.as_object().into_iter().flatten() {
        match k.as_str() {
            "_limit" => limit = v.as_u64().map(|n| n as u32).unwrap_or(default_limit),
            "_order" => {
                // `created_at DESC` is the filter map's `sort=-created_at`.
                let text = v.as_str().unwrap_or_default();
                let mut parts = text.split_whitespace();
                if let Some(field) = parts.next() {
                    let desc = parts.next().is_some_and(|d| d.eq_ignore_ascii_case("desc"));
                    filters.insert("sort".to_string(), format!("{}{field}", if desc { "-" } else { "" }));
                }
            }
            _ => {
                let text = match v { Value::String(s) => s.clone(), other => other.to_string() };
                filters.insert(k.clone(), text);
            }
        }
    }
    (filters, limit)
}

#[async_trait]
impl WorkflowDefinition for FileProcessingWorkflow {
    fn spec(&self) -> &WorkflowSpec {
        static SPEC: OnceLock<WorkflowSpec> = OnceLock::new();
        SPEC.get_or_init(|| WorkflowSpec::from_json(FILE_PROCESSING_SPEC))
    }

    #[allow(unused_variables)]
    async fn perform(&self, ctx: &WriteCtx, call: &Call<'_>) -> ServiceResult<Value> {
        match call.step {
            "load_job" => {
                let (filters, limit) = filters_of(call.params, 1);
                let (rows, _) = self.services.processing_job.list(1, limit, filters).await?;
                match rows.into_iter().next() {
                    Some(found) => to_json(&found),
                    None => Err(ServiceError::NotFound),
                }
            }
            "mark_running" => self.actions.start_job(ctx, call.params, call.context).await,
            "load_file" => {
                let (filters, limit) = filters_of(call.params, 1);
                let (rows, _) = self.services.stored_file.list(1, limit, filters).await?;
                match rows.into_iter().next() {
                    Some(found) => to_json(&found),
                    None => Err(ServiceError::NotFound),
                }
            }
            "load_bucket" => {
                let (filters, limit) = filters_of(call.params, 1);
                let (rows, _) = self.services.bucket.list(1, limit, filters).await?;
                match rows.into_iter().next() {
                    Some(found) => to_json(&found),
                    None => Err(ServiceError::NotFound),
                }
            }
            "process_image_thumbnail" => self.actions.generate_image_thumbnail(ctx, call.params, call.context).await,
            "store_image_thumbnail" => self.actions.store_file(ctx, call.params, call.context).await,
            "update_file_thumbnail" => {
                let id = record_id(call)?;
                match self.services.stored_file.partial_update(&id, fields_of(call.params)).await? {
                    Some(saved) => to_json(&saved),
                    None => Err(ServiceError::NotFound),
                }
            }
            "process_video_thumbnail" => self.actions.extract_video_frame(ctx, call.params, call.context).await,
            "store_video_thumbnail" => self.actions.store_file(ctx, call.params, call.context).await,
            "update_file_video_thumbnail" => {
                let id = record_id(call)?;
                match self.services.stored_file.partial_update(&id, fields_of(call.params)).await? {
                    Some(saved) => to_json(&saved),
                    None => Err(ServiceError::NotFound),
                }
            }
            "process_document_preview" => self.actions.generate_document_preview(ctx, call.params, call.context).await,
            "store_document_preview" => self.actions.store_file(ctx, call.params, call.context).await,
            "update_file_document_preview" => {
                let id = record_id(call)?;
                match self.services.stored_file.partial_update(&id, fields_of(call.params)).await? {
                    Some(saved) => to_json(&saved),
                    None => Err(ServiceError::NotFound),
                }
            }
            "process_compression" => self.actions.compress_file(ctx, call.params, call.context).await,
            "store_compressed_file" => self.actions.store_file(ctx, call.params, call.context).await,
            "update_file_compression" => {
                let id = record_id(call)?;
                match self.services.stored_file.partial_update(&id, fields_of(call.params)).await? {
                    Some(saved) => to_json(&saved),
                    None => Err(ServiceError::NotFound),
                }
            }
            "update_bucket_compression_stats" => {
                let id = record_id(call)?;
                match self.services.bucket.partial_update(&id, fields_of(call.params)).await? {
                    Some(saved) => to_json(&saved),
                    None => Err(ServiceError::NotFound),
                }
            }
            "process_virus_scan" => self.actions.scan_file_for_threats(ctx, call.params, call.context).await,
            "update_scan_safe" => {
                let id = record_id(call)?;
                match self.services.stored_file.partial_update(&id, fields_of(call.params)).await? {
                    Some(saved) => to_json(&saved),
                    None => Err(ServiceError::NotFound),
                }
            }
            "update_scan_warning" => {
                let id = record_id(call)?;
                match self.services.stored_file.partial_update(&id, fields_of(call.params)).await? {
                    Some(saved) => to_json(&saved),
                    None => Err(ServiceError::NotFound),
                }
            }
            "update_scan_threat" => self.actions.quarantine_file(ctx, call.params, call.context).await,
            "process_deduplication" => self.actions.calculate_file_hash(ctx, call.params, call.context).await,
            "check_existing_hash" => {
                let (filters, limit) = filters_of(call.params, 1);
                let (rows, _) = self.services.content_hash.list(1, limit, filters).await?;
                match rows.into_iter().next() {
                    Some(found) => to_json(&found),
                    None => Err(ServiceError::NotFound),
                }
            }
            "update_existing_hash" => {
                let id = record_id(call)?;
                match self.services.content_hash.partial_update(&id, fields_of(call.params)).await? {
                    Some(saved) => to_json(&saved),
                    None => Err(ServiceError::NotFound),
                }
            }
            "link_file_hash" => {
                let id = record_id(call)?;
                match self.services.stored_file.partial_update(&id, fields_of(call.params)).await? {
                    Some(saved) => to_json(&saved),
                    None => Err(ServiceError::NotFound),
                }
            }
            "create_new_hash" => {
                let dto: crate::presentation::dto::CreateContentHashDto = serde_json::from_value(call.params.clone())
                    .map_err(|e| ServiceError::Validation(format!("step `{}`: the parameters do not make a CreateContentHashDto: {e}", call.step)))?;
                let saved = self.services.content_hash.create(dto).await?;
                to_json(&saved)
            }
            "mark_complete" => self.actions.complete_job(ctx, call.params, call.context).await,
            "schedule_retry" => self.actions.requeue_job(ctx, call.params, call.context).await,
            "mark_failed" => self.actions.fail_job(ctx, call.params, call.context).await,
            "compensate:cleanup_partial_storage" => self.actions.delete_file(ctx, call.params, call.context).await,
            "compensate:cleanup_thumbnails" => self.actions.delete_file(ctx, call.params, call.context).await,
            other => Err(ServiceError::Internal(format!("step `{other}` has no action in FileProcessing"))),
        }
    }

    #[allow(unused_variables)]
    async fn function(&self, ctx: &WriteCtx, name: &str, args: &[Value]) -> ServiceResult<Value> {
        match name {
            "exponential_backoff" => self.actions.fn_exponential_backoff(ctx, args).await,
            other => Err(ServiceError::Internal(format!("function `{other}` is not declared by FileProcessing"))),
        }
    }
}

